			netif_tx_disable(priv->netdev);
			cancel_delayed_work_sync(&priv->__rseq_link_work);
			if (priv->__rseq_napi_enabled) {
						napi_disable(&priv->napi);
						priv->__rseq_napi_enabled = false;
			}
